from notes.download import download_note
from notes.errors import AuthenticationRequired, NoteNotFound
from notes.store import Note, NoteStore

store = NoteStore([Note("n1", "alice", "T", "text")])
for uid in (None, ""):
    try:
        download_note(store, uid, "n1")
    except AuthenticationRequired:
        pass
    else:
        raise AssertionError("expected AuthenticationRequired")
try:
    download_note(store, "bob", "n1")  # not owner
except NoteNotFound:
    pass
else:
    raise AssertionError("expected NoteNotFound for other owner")
